-- data_028_of_120.sql: intelligence dataset 2026-09-29, part 28 of 120. Run in order; safe to re-run.

insert into public.sports_teams (external_key, name, short_name, sport, league, country, city, stadium, stadium_capacity, stadium_capacity_source_url, founded_year, domain, ownership_type, ownership_summary, ownership_source_url, revenue, revenue_currency, revenue_season, revenue_source_name, revenue_source_url, valuation, valuation_currency, valuation_year, valuation_source_name, valuation_source_url, social_followers, social_as_of, social_source_url, social_platforms, notes, sources, verification, source)
  values ('premier-league--arsenal', 'Arsenal Football Club', 'Arsenal', 'football', 'Premier League', 'England', 'London', 'Emirates Stadium', 60704, 'https://en.wikipedia.org/wiki/Emirates_Stadium', 1886, 'arsenal.com', 'individual_family', 'Arsenal is wholly owned by Stan Kroenke through Kroenke Sports & Entertainment (KSE UK Inc), which took the club private in August 2018 after buying Alisher Usmanov''s 30% stake and compulsorily purchasing the remaining minority shares. No outside private equity, sovereign or institutional co-investor has been reported.', 'https://en.wikipedia.org/wiki/Ownership_of_Arsenal_F.C._&_W.F.C.', 691000000, 'GBP', '2024-25', 'Arsenal FC (financial results for 2024/25)', 'https://www.arsenal.com/news/financial-results-for-202425-axV959A5jyCF', 5400000000, 'USD', 2026, 'Forbes (The World''s Most Valuable Soccer Teams 2026)', 'https://www.forbes.com/sites/justinteitelbaum/2026/05/29/the-worlds-most-valuable-soccer-teams-2026/', 108700000, 'May 2025', 'https://premierleaguenow.co.uk/2025/05/01/premier-league-clubs-most-social-media-followers/', '[{"platform": "Instagram", "followers": 30162009, "as_of": "January 2025", "source_url": "https://www.planetfootball.com/champions-league/champions-league-clubs-social-media-following-ranked"}, {"platform": "X", "followers": 22556897, "as_of": "January 2025", "source_url": "https://www.planetfootball.com/champions-league/champions-league-clubs-social-media-following-ranked"}, {"platform": "TikTok", "followers": 8100000, "as_of": "January 2025", "source_url": "https://www.planetfootball.com/champions-league/champions-league-clubs-social-media-following-ranked"}, {"platform": "YouTube", "followers": 4420000, "as_of": "January 2025", "source_url": "https://www.planetfootball.com/champions-league/champions-league-clubs-social-media-following-ranked"}, {"platform": "Instagram", "followers": 32397197, "as_of": "2026-09-28", "source_url": "https://hypeauditor.com/instagram/arsenal/"}]'::jsonb, 'Single-owner club with no third-party institutional capital: no PE, sovereign or family-office minority stake has been reported, and no sale process is known as of September 2026. Ownership is via KSE UK Inc, 100% owned by Stan Kroenke; some secondary sources quote 98.89% or 99.7% for interim stages of the 2018 squeeze-out, but the club and Wikipedia describe it as wholly owned. Revenue: club-reported £691.0m for 2024-25 (Deloitte Money League 2026 shows €821.7m, 7th place; Forbes quotes $895m). Valuations diverge by publisher: Forbes 2026 $5.4bn (8th, +59% YoY, after 2025-26 Premier League title), Sportico 2026 $5.43bn (7th), Forbes 2025 $3.4bn, CNBC 2025 8th. The 2018 buyout was funded by a £557m Deutsche Bank loan at KSE level, since replaced by owner loans; the club owed KSE £324.1m per its latest accounts (low-interest, not interest-free). Social totals come from aggregator sites, not the club, and vary by date; the January 2025 per-platform breakdown from Planet Football excludes Facebook (Facebook alone shows ~50.9m). September 2025 saw a board restructuring including the departure of Executive Vice-Chair Tim Lewis.', '["https://en.wikipedia.org/wiki/Ownership_of_Arsenal_F.C._&_W.F.C.", "https://www.arsenal.com/the-arsenal-board", "https://www.consultancy.uk/news/18261/fans-wary-of-hidden-fees-as-kroenke-takes-100-arsenal-stake", "https://www.arsenal.com/news/financial-results-for-202425-axV959A5jyCF", "https://arseblog.news/2026/01/arsenal-continue-steady-growth-maintain-7th-place-in-deloitte-money-league/", "https://www.deloitte.com/uk/en/services/consulting-financial/analysis/deloitte-football-money-league.html", "https://www.forbes.com/sites/justinteitelbaum/2025/05/30/the-worlds-most-valuable-soccer-teams-2025/", "https://www.forbes.com/sites/justinteitelbaum/2026/05/29/the-worlds-most-valuable-soccer-teams-2026/", "https://www.sportico.com/valuations/teams/2026/most-valuable-soccer-teams-2026-real-madrid-barcelona-1234890790/", "https://www.sportico.com/feature/soccer-teams-football-club-ranking-list-1234721408/", "https://hypeauditor.com/instagram/arsenal/", "https://premierleaguenow.co.uk/2025/05/01/premier-league-clubs-most-social-media-followers/", "https://www.planetfootball.com/champions-league/champions-league-clubs-social-media-following-ranked", "https://en.wikipedia.org/wiki/Emirates_Stadium", "https://en.wikipedia.org/wiki/Arsenal_F.C.", "https://www.forbes.com/sites/mikeozanian/2018/08/07/kroenke-buying-usmanovs-arsenal-stake-in-2-2-billion-lbo/", "https://uk.investing.com/news/stock-market-news/us-billionaire-kroenke-seeks-to-buy-all-of-arsenal-1275273", "https://bleacherreport.com/articles/2789839-stan-kroenke-launches-arsenal-takeover-bid-values-club-at-18b", "https://www.arsenaltrust.org/feed/afc-finances/2020/AST-Debt-Redemption-KSE", "https://www.goal.com/en/news/arsenal-120m-bank-of-england-loan/1bom1d3f102fd1v94k39u2rlsk", "https://arsenalnews.co.uk/2025/03/20/arsenal-now-owe-324-1million-to-owners-kroenke-sports-entertainment/", "https://www.arsenaltrust.org/feed/surveys/2018/Responses-from-AST-members-Arsenal-shareholders-compulsory-purchase-shares-by-Kroenke"]'::jsonb, '[]'::jsonb, 'web_research')
  on conflict (external_key) do update set name = excluded.name, short_name = excluded.short_name, sport = excluded.sport, league = excluded.league, country = excluded.country, city = excluded.city, stadium = excluded.stadium, stadium_capacity = excluded.stadium_capacity, stadium_capacity_source_url = excluded.stadium_capacity_source_url, founded_year = excluded.founded_year, domain = excluded.domain, ownership_type = excluded.ownership_type, ownership_summary = excluded.ownership_summary, ownership_source_url = excluded.ownership_source_url, revenue = excluded.revenue, revenue_currency = excluded.revenue_currency, revenue_season = excluded.revenue_season, revenue_source_name = excluded.revenue_source_name, revenue_source_url = excluded.revenue_source_url, valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, valuation_year = excluded.valuation_year, valuation_source_name = excluded.valuation_source_name, valuation_source_url = excluded.valuation_source_url, social_followers = excluded.social_followers, social_as_of = excluded.social_as_of, social_source_url = excluded.social_source_url, social_platforms = excluded.social_platforms, notes = excluded.notes, sources = excluded.sources, verification = excluded.verification, source = excluded.source;
